package com.pridesys.ticketing.entity;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="password_reset_tokens") public class ResetTokenEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(name="user_id",nullable=false) long userId; @Column(name="token_hash",nullable=false,unique=true,length=64) String tokenHash; @Column(name="expires_at",nullable=false) Instant expiresAt; @Column(name="used_at") Instant usedAt; protected ResetTokenEntity(){} public ResetTokenEntity(long u,String h,Instant e){userId=u;tokenHash=h;expiresAt=e;} public Long getId(){return id;} public long getUserId(){return userId;} public Instant getExpiresAt(){return expiresAt;} public Instant getUsedAt(){return usedAt;} public void setUsedAt(Instant v){usedAt=v;} }
